/// Parse a number literal string to f64
fn parse_number(text: &JsString) -> f64 {
    let s = text.as_ref();
    // Handle hex, binary, octal
    if s.starts_with("0x") || s.starts_with("0X") {
        i64::from_str_radix(s.get(2..).unwrap_or(""), 16).map(|n| n as f64).unwrap_or(f64::NAN)
    } else if s.starts_with("0b") || s.starts_with("0B") {
        i64::from_str_radix(s.get(2..).unwrap_or(""), 2).map(|n| n as f64).unwrap_or(f64::NAN)
    } else if s.starts_with("0o") || s.starts_with("0O") {
        i64::from_str_radix(s.get(2..).unwrap_or(""), 8).map(|n| n as f64).unwrap_or(f64::NAN)
    } else {
        // Remove underscores and parse
        let cleaned: String = s.chars().filter(|c| *c != '_').collect();
        cleaned.parse().unwrap_or(f64::NAN)
    }
}

/// Parse a string literal, handling escape sequences
fn parse_string_literal(text: &JsString) -> JsString {
    let s = text.as_ref();
    // Remove quotes
    if s.len() < 2 {
        return JsString::from("");
    }
    let inner = s.get(1..s.len()-1).unwrap_or("");
    // TODO: Handle escape sequences properly
    JsString::from(inner)
}

